param([ValidateSet('build','combined','scores','output','split','tiles')][string]$Action='build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$sourcePath='D:\projects\fla-output-failure-replay-source-r1.json'
$m=[IO.File]::ReadAllText($sourcePath)|ConvertFrom-Json
function Verify-File([string]$Path,[string]$Sha){if((Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $Sha){throw ('Changed input: '+$Path)}}
Verify-File $PSCommandPath $m.script_sha256
$prior=[IO.File]::ReadAllText($m.prior_run)|ConvertFrom-Json
if($prior.reason -ne 'completed' -or -not $prior.host_checks_pass -or @($prior.after_processes).Count -ne 0){throw 'Long run is not fully complete'}
$repo=$m.repo.Replace('/','\');$seed=$m.seed.Replace('/','\');$commit=$m.source_commit
$bundle=Join-Path 'D:\projects' $m.bundle;Verify-File $bundle $m.bundle_sha256
if(-not(Test-Path $repo)){
 & git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'}
 & git -C $seed worktree add --detach $repo $commit;if($LASTEXITCODE -ne 0){throw 'Worktree failed'}
}
if((& git -C $repo rev-parse HEAD).Trim() -ne $commit -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$inputs=@()
foreach($e in $m.source_sha256.PSObject.Properties){
 Verify-File (Join-Path $repo $e.Name) $e.Value
 $inputs+=@{file=$e.Name;sha256=$e.Value}
}
$build=Join-Path $repo 'build\output-failure-replay'
$exe=Join-Path $build 'qrt-fla-output-failure-replay.exe'
$name='fla-output-failure-replay-'+$Action+'-r1'
$out=Join-Path $repo ('build\'+$name);$specPath=$out+'.json'
foreach($p in @($out,$specPath)){if(Test-Path $p){throw 'Evidence exists'}}
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$commit
 command_file=$PSCommandPath;command_file_sha256=$m.script_sha256
 source_manifest_sha256=(Get-FileHash $sourcePath -Algorithm SHA256).Hash.ToLowerInvariant()
 source_inputs=$inputs;prior_run=$m.prior_run;prior_run_sha256=(Get-FileHash $m.prior_run -Algorithm SHA256).Hash.ToLowerInvariant()
 model='none; standalone replay of actual completed failed native tensors';model_loaded=$false
 inference_acceptance=$false;performance_acceptance=$false;completion_guard_ms=100;mode=$Action
}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
if($Action -eq 'build'){
 if(Test-Path $build){throw 'Build evidence exists'}
 $null=New-Item -ItemType Directory -Path $build
 $hipcc=(Get-Command hipcc.exe -ErrorAction Stop).Source
 $vs=@('D:\BuildTools\Common7\Tools\VsDevCmd.bat','C:\Program Files\Microsoft Visual Studio\2022\BuildTools\Common7\Tools\VsDevCmd.bat','C:\Program Files (x86)\Microsoft Visual Studio\2022\BuildTools\Common7\Tools\VsDevCmd.bat')|Where-Object {Test-Path $_}|Select-Object -First 1
 if(-not $vs){throw 'Missing MSVC setup'}
 $units=@($m.translation_units|ForEach-Object {'"'+(Join-Path $repo $_)+'"'})
 $compiler='"'+$hipcc+'" -std=c++17 -O2 --offload-arch=gfx1151 -DQRT_SM121_DPP_REDUCTION=1 -DQRT_SM121_COMPACT_NORMALIZE=1 '+($units -join ' ')+' -o "'+$exe+'"'
 $lines=@('@echo off',('call "'+$vs+'" -arch=x64 -host_arch=x64 >nul'),'if not "%errorlevel%"=="0" exit /b 21',$compiler,'exit /b %errorlevel%')
 $batch=Join-Path $build 'build.cmd'
 [IO.File]::WriteAllText($batch,($lines -join "`r`n")+"`r`n",[Text.UTF8Encoding]::new($false))
 $spec.executable='C:\Windows\System32\cmd.exe';$spec.arguments=@('/d','/s','/c',$batch)
 $spec.compiler_command=$compiler;$spec.translation_units=@($m.translation_units)
 $spec.compiler_sha256=(Get-FileHash $hipcc -Algorithm SHA256).Hash.ToLowerInvariant()
 $spec.command_batch_sha256=(Get-FileHash $batch -Algorithm SHA256).Hash.ToLowerInvariant()
 $timeout=180
}else{
 $buildRecord=Join-Path $repo 'build\fla-output-failure-replay-build-r1\run-record.json'
 $buildRun=[IO.File]::ReadAllText($buildRecord)|ConvertFrom-Json
 if($buildRun.reason -ne 'completed' -or $buildRun.exit_code -ne 0 -or -not $buildRun.host_checks_pass){throw 'Build not qualified'}
 $meta=[IO.File]::ReadAllText((Join-Path $build 'build-provenance.json'))|ConvertFrom-Json
 if($meta.repo_commit -ne $commit){throw 'Wrong replay build'}
 Verify-File $exe $meta.artifact.sha256
 $captureManifestPath='D:\projects\fla-output-failure-replay-inputs-r1.json'
 $capture=[IO.File]::ReadAllText($captureManifestPath)|ConvertFrom-Json
 Verify-File $m.prior_run $capture.prior_run_sha256
 if($prior.exit_code -ne 5 -or @($capture.files.PSObject.Properties).Count -ne 8){throw 'Requires actual failed captured run'}
 foreach($e in $capture.files.PSObject.Properties){
  $path=Join-Path $capture.directory $e.Name;Verify-File $path $e.Value.sha256
  if((Get-Item $path).Length -ne $e.Value.bytes){throw 'Capture size changed'}
 }
 $c=[IO.File]::ReadAllText((Join-Path $capture.directory 'capture.json'))|ConvertFrom-Json
 if(-not $c.complete -or -not $c.stage_completed -or $c.guard_accepted -or $c.kernel_retried -or $c.tokens -lt 1 -or $c.tokens -gt 1024){throw 'Invalid capture contract'}
 Verify-File $m.exp2_table $m.exp2_table_sha256
 $env:QRT_FLA_GDN_SM121_EXP2_TABLE=$m.exp2_table
 $spec.executable=$exe;$spec.arguments=@($capture.directory,[string]$c.tokens,$Action)
 $spec.capture=$capture;$spec.capture_manifest_sha256=(Get-FileHash $captureManifestPath -Algorithm SHA256).Hash.ToLowerInvariant()
 $spec.exp2_table=$m.exp2_table;$spec.exp2_table_sha256=$m.exp2_table_sha256
 $spec.build_run_sha256=(Get-FileHash $buildRecord -Algorithm SHA256).Hash.ToLowerInvariant()
 $spec.build_metadata_sha256=(Get-FileHash (Join-Path $build 'build-provenance.json') -Algorithm SHA256).Hash.ToLowerInvariant()
 $timeout=60
}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
if($r.reason -ne 'completed' -or -not $r.host_checks_pass){throw 'Native completion or host checks failed'}
if($Action -eq 'build'){
 if($r.exit_code -ne 0){throw 'Build failed'}
 $meta=[ordered]@{repo_commit=$commit;dirty_tree=$false;translation_units=@($m.translation_units);source_inputs=$inputs;compiler_command=$compiler;compiler_sha256=$spec.compiler_sha256;command_batch_sha256=$spec.command_batch_sha256
  source_scope='All checked-in headers and C++ sources in GDN and accumulator directories plus guard support; translation units identify actual compilation entry points.'
  artifact=@{file=[IO.Path]::GetFileName($exe);bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()}
  model_loaded=$false;inference_acceptance=$false;performance_acceptance=$false}
 [IO.File]::WriteAllText((Join-Path $build 'build-provenance.json'),($meta|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false))
}elseif($r.exit_code -notin @(0,3,4)){throw 'Replay API/input error'}
Get-Content (Join-Path $out 'product.stdout.jsonl') -Tail 18

