$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$sourcePath='D:\projects\gb10-prefix128-layer33-native-source-r1.json'
$m=[IO.File]::ReadAllText($sourcePath)|ConvertFrom-Json
function Verify-File([string]$Path,[string]$Sha){if((Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $Sha){throw ('Changed input: '+$Path)}}
Verify-File $PSCommandPath $m.script_sha256
$prior=[IO.File]::ReadAllText($m.prior_run)|ConvertFrom-Json
if($prior.reason -ne 'completed' -or -not $prior.host_checks_pass -or @($prior.after_processes).Count -ne 0){throw 'Long run not fully complete'}
$repo=$m.repo.Replace('/','\');$commit=$m.source_commit
if((& git -C $repo rev-parse HEAD).Trim() -ne $commit -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Provider source mismatch'}
$metadata=Join-Path $repo 'build\fla\build-provenance.json';Verify-File $metadata $m.build_metadata_sha256
$build=[IO.File]::ReadAllText($metadata)|ConvertFrom-Json
if($build.repo_commit -ne $commit -or $build.dirty_tree){throw 'Wrong provider build'}
$kernels=Join-Path $repo 'build\fla';$dll=Join-Path $kernels 'qrt_fla_chunk_gdn_provider.dll'
foreach($f in $build.sources){Verify-File $f.path $f.sha256}
foreach($f in $build.artifacts){Verify-File (Join-Path $kernels $f.file) $f.sha256}
Verify-File $m.tool_metadata $m.tool_metadata_sha256
$tool=[IO.File]::ReadAllText($m.tool_metadata)|ConvertFrom-Json
if($tool.repo_commit -ne $m.tool_source_commit){throw 'Replay source mismatch'}
Verify-File $tool.artifact.file $tool.artifact.sha256
foreach($f in $tool.source_inputs){Verify-File $f.file $f.sha256}
$fixture=Join-Path 'D:\projects' $m.fixture.directory
$archive=Join-Path 'D:\projects' $m.fixture.archive;Verify-File $archive $m.fixture.sha256
if(Test-Path $fixture){throw 'Input extraction exists'}
$null=New-Item -ItemType Directory -Path $fixture
& tar.exe -xf $archive -C $fixture;if($LASTEXITCODE -ne 0){throw 'Extraction failed'}
$manifest=Join-Path $fixture 'manifest.json';Verify-File $manifest $m.fixture.manifest_sha256
$inputs=[IO.File]::ReadAllText($manifest)|ConvertFrom-Json
if($inputs.layer -ne 33 -or $inputs.first_position -ne 114688 -or $inputs.tokens -ne 8192 -or $inputs.original_transaction -ne 14 -or -not $inputs.original512_output_ids_and_full_first_logits_reproduced -or -not $inputs.reference_qualified){throw 'Wrong reference window'}
foreach($f in $inputs.files.PSObject.Properties){
 $p=Join-Path $fixture $f.Name;Verify-File $p $f.Value.sha256
 if((Get-Item $p).Length -ne $f.Value.bytes){throw 'Input size changed'}
}
if(@(Get-ChildItem $fixture -File).Count -ne 6){throw 'Input inventory changed'}
$name='gb10-prefix128-layer33-seeded-key-major-r1';$out=Join-Path $repo ('build\'+$name)
$outputs=$out+'-outputs';$specPath=$out+'.json';$toolCopy=$out+'-tool'
foreach($p in @($out,$outputs,$specPath,$toolCopy,$m.capture_directory)){if(Test-Path $p){throw 'Evidence exists'}}
$null=New-Item -ItemType Directory -Path $toolCopy
$exe=Join-Path $toolCopy 'qrt-fla-seeded-capture-replay.exe'
Copy-Item -LiteralPath $tool.artifact.file -Destination $exe;Verify-File $exe $tool.artifact.sha256
Verify-File $m.profile $m.profile_sha256
foreach($e in @(Get-ChildItem Env:|Where-Object {$_.Name.StartsWith('QRT_FLA_')})){[Environment]::SetEnvironmentVariable($e.Name,$null,'Process')}
$environment=[ordered]@{}
foreach($line in [IO.File]::ReadAllLines($m.profile)){if($line -match '^(QRT_FLA_[A-Z0-9_]+)=(.*)$'){$environment[$Matches[1]]=$Matches[2]}}
$environment['QRT_FLA_GDN_CAPTURE_OUTPUT_FAILURE_DIR']=$m.capture_directory
foreach($key in $environment.Keys){[Environment]::SetEnvironmentVariable($key,[string]$environment[$key],'Process')}
foreach($table in $m.tables){Verify-File $table.path $table.sha256}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
$spec=[ordered]@{executable=$exe;arguments=@($kernels,$dll,$fixture,$outputs,'8192','key-major');working_directory=$repo;repo_commit=$commit
 command_file=$PSCommandPath;command_file_sha256=$m.script_sha256;source_manifest_sha256=(Get-FileHash $sourcePath -Algorithm SHA256).Hash.ToLowerInvariant()
 model='GB10 Qwen3.6-35B-A3B original131072-token prompt, layer33 transaction14 positions114688..122879';model_loaded=$false;native_tensor_inputs=$true
 inference_acceptance=$false;performance_acceptance=$false;purpose='Independent seeded component comparison of original GB10 operands and state. No full-model acceptance. Preserve original100 ms provider guard and record any rejected completed output. Repeat exact seed and zero-state negative control only if preceding launch completed successfully.'
 tool_source_commit=$m.tool_source_commit;tool_metadata_sha256=$m.tool_metadata_sha256;tool_source_inputs=$tool.source_inputs
 build_metadata_sha256=$m.build_metadata_sha256;provider_sha256=(Get-FileHash $dll -Algorithm SHA256).Hash.ToLowerInvariant()
 reference_manifest_sha256=$m.fixture.manifest_sha256;reference_capture_sha256=$inputs.reference_capture_sha256;reference_source_commit=$inputs.source_commit
 reference_all512_and_logits_pass=$true;interface_state_layout='key-major';capture_state_layout=$inputs.state_layout;environment=$environment
 prior_run_sha256=(Get-FileHash $m.prior_run -Algorithm SHA256).Hash.ToLowerInvariant();tables=$m.tables
}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 12),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds 90|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks_pass|ConvertTo-Json
if($r.reason -ne 'completed' -or -not $r.host_checks_pass -or $r.exit_code -notin @(0,2,6)){throw 'Diagnostic completion failed'}
$files=@()
if(Test-Path $outputs){$files=@(Get-ChildItem $outputs -File|ForEach-Object{@{file=$_.Name;bytes=$_.Length;sha256=(Get-FileHash $_.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}})}
[IO.File]::WriteAllText((Join-Path $out 'output-manifest.json'),($files|ConvertTo-Json -Depth 5),[Text.UTF8Encoding]::new($false))
if(Test-Path (Join-Path $outputs 'result.json')){Get-Content (Join-Path $outputs 'result.json') -Raw}
Get-Content (Join-Path $out 'product.stderr.log') -Tail 10
